def ultima_versao(df, chaves, ordem):
    nulos = df.filter(" OR ".join(f"{c} IS NULL" for c in ordem)).limit(1).count()
    if nulos:
        raise ValueError(f"Colunas de ordenação com nulo: {ordem}")
    janela = Window.partitionBy(*chaves).orderBy(*[F.col(c).desc() for c in ordem])
    return df.withColumn("_rn", F.row_number().over(janela)).filter("_rn = 1").drop("_rn")

resultado = ultima_versao(eventos, ["id"], ["ts", "versao"])

