def conformar(df, contrato):
    extras = sorted(set(df.columns) - set(contrato))
    if extras:
        print(f"Colunas fora do contrato: {extras}")
    return df.select(*[
        (F.col(c).cast(t) if c in df.columns else F.lit(None).cast(t)).alias(c)
        for c, t in contrato.items()
    ])

resultado = conformar(evento, {"id": "bigint", "valor": "decimal(10,2)", "nome": "string"})
